import sys
from collections import Counter

def main():
    input = sys.stdin.read().split()
    T = int(input[0])
    index = 1
    result = []
    for _ in range(T):
        N = int(input[index])
        A = input[index + 1]
        B = input[index + 2]
        index += 3
        A_count = Counter(A)
        B_count = Counter(B)
        S = []
        for i in range(N * 2):
            if i % 2 == 0:
                min_char = None
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    if A_count[c] > 0:
                        if min_char is None or c < min_char:
                            min_char = c
                A_count[min_char] -= 1
                S.append(min_char)
            else:
                max_char = None
                for c in 'abcdefghijklmnopqrstuvwxyz':
                    if B_count[c] > 0:
                        if max_char is None or c > max_char:
